    logic readback_err;
    logic readback_done;
    logic [63:0] readback_data;
    always_comb begin
        automatic logic [63:0] readback_data_var;
        readback_data_var = '0;
        if(rd_mux_addr == 5'h0) begin
            readback_data_var[0] = field_storage.FILTER_CONFIG.read_allowed.value;
            readback_data_var[1] = field_storage.FILTER_CONFIG.write_allowed.value;
            readback_data_var[4] = field_storage.FILTER_CONFIG.entry_enabled.value;
            readback_data_var[8] = field_storage.FILTER_CONFIG.allow_ns.value;
            readback_data_var[14:12] = hwif_in.FILTER_CONFIG.data_bus_width.next;
            readback_data_var[19:16] = field_storage.FILTER_CONFIG.src_id.value;
            readback_data_var[23:20] = field_storage.FILTER_CONFIG.group_id.value;
            readback_data_var[24] = field_storage.FILTER_CONFIG.allow_burst.value;
            readback_data_var[63] = field_storage.FILTER_CONFIG.locked.value;
        end
        if(rd_mux_addr == 5'h8) begin
            readback_data_var[55:0] = field_storage.START_ADDR.start_addr.value;
        end
        if(rd_mux_addr == 5'h10) begin
            readback_data_var[55:0] = field_storage.END_ADDR.end_addr.value;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
